import{_ as p,a0 as i,w as a,s as u,ao as e,I as l,x as n,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用這個 Python 程序記錄你的活動 | LCTT x X-CMD","titleTemplate":false,"description":"使用這個 Python 程序記錄你的活動 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用這個 Python 程序記錄你的活動 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用這個 Python 程序記錄你的活動 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200118 Keep a journal of your activities with this Python program","title":"使用這個 Python 程序記錄你的活動","tag":"202002","desc":""},"relativePath":"202002/20200118 Keep a journal of your activities with this Python program.md","filePath":"[post].md"}'),d={name:"202002/20200118 Keep a journal of your activities with this Python program.md"};function f(m,t,j,g,y,T){const s=i("Link");return a(),u("div",null,[t[28]||(t[28]=e('<h1 id="使用這個-python-程序記錄你的活動" tabindex="-1">使用這個 Python 程序記錄你的活動 <a class="header-anchor" href="#使用這個-python-程序記錄你的活動" aria-label="Permalink to “使用這個 Python 程序記錄你的活動”">​</a></h1><blockquote><p>jrnl 可以創建可搜索、帶時間戳、可導出、加密的（如果需要）的日常活動日誌。在我們的 20 個使用開源提升生產力的系列的第八篇文章中瞭解更多。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202002/03/105455tx03zo2pu7woyusp.jpg" alt=""></p><p>去年，我在 19 天裏給你介紹了 19 個新（對你而言）的生產力工具。今年，我換了一種方式：使用你在使用或者還沒使用的工具，構建一個使你可以在新一年更加高效的環境。</p><h3 id="使用-jrnl-記錄日誌" tabindex="-1">使用 jrnl 記錄日誌 <a class="header-anchor" href="#使用-jrnl-記錄日誌" aria-label="Permalink to “使用 jrnl 記錄日誌”">​</a></h3><p>在我的公司，許多人會在下班之前在 Slack 上發送一個“一天結束”的狀態。在有着許多項目和全球化的團隊裏，這是一個分享你已完成、未完成以及你需要哪些幫助的一個很好的方式。但有時候我太忙了，以至於我忘了做了什麼。這時候就需要記錄日誌了。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_8-1.png" alt="jrnl" title="jrnl"></p>',7)),l("p",null,[t[1]||(t[1]=n("打開一個文本編輯器並在你做一些事的時候添加一行很容易。但是在需要找出你在什麼時候做的筆記，或者要快速提取相關的行時會有挑戰。幸運的是，",-1)),o(s,{href:"https://jrnl.sh/"},{default:r(()=>[...t[0]||(t[0]=[n("jrnl",-1)])]),_:1}),t[2]||(t[2]=n(" 可以提供幫助。",-1))]),t[29]||(t[29]=e('<p>jrnl 能讓你在命令列中快速輸入條目、搜索過去的條目並導出為 HTML 和 Markdown 等富文本格式。你可以有多個日誌，這意味着你可以將工作條目與私有條目分開。它將條目存儲為純文本，因此即使 jrnl 停止工作，數據也不會丟失。</p><p>由於 jrnl 是一個 Python 程序，最簡單的安裝方法是使用 <code>pip3 install jrnl</code>。這將確保你獲得最新和最好的版本。第一次運行它會詢問一些問題，接下來就能正常使用。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_8-2.png" alt="jrnl&#39;s first run" title="jrnl&#39;s first run"></p><p>現在，每當你需要做筆記或記錄日誌時，只需輸入 <code>jrnl &lt;some text&gt;</code>，它將帶有時間戳的記錄保存到默認文件中。你可以使用 <code>jrnl -on YYYY-MM-DD</code> 搜索特定日期條目，<code>jrnl -from YYYY-MM-DD</code> 搜索在那日期之後的條目，以及用 <code>jrnl -to YYYY-MM-DD</code> 搜索到那日期的條目。搜索詞可以與 <code>-and</code> 參數結合使用，允許像 <code>jrnl -from 2019-01-01 -and -to 2019-12-31</code> 這類搜索。</p>',4)),l("p",null,[t[4]||(t[4]=n("你還可以使用 ",-1)),t[5]||(t[5]=l("code",null,"--edit",-1)),t[6]||(t[6]=n(" 標誌編輯日誌中的條目。開始之前，通過編輯文件 ",-1)),t[7]||(t[7]=l("code",null,"~/.config/jrnl/jrnl.yaml",-1)),t[8]||(t[8]=n(" 來設置默認編輯器。你還可以指定日誌使用什麼文件、用於標籤的特殊字符以及一些其他選項。現在，重要的是設置編輯器。我使用 Vim，jrnl 的文檔中有一些使用其他編輯器如 VSCode 和 Sublime Text 的",-1)),o(s,{href:"https://jrnl.sh/recipes/#external-editors"},{default:r(()=>[...t[3]||(t[3]=[n("有用提示",-1)])]),_:1}),t[9]||(t[9]=n("。",-1))]),t[30]||(t[30]=e(`<p><img src="https://opensource.com/sites/default/files/uploads/productivity_8-3.png" alt="Example jrnl config file" title="Example jrnl config file"></p><p>jrnl 還可以加密日誌文件。通過設置全局 <code>encrypt</code> 變量，你將告訴 jrnl 加密你定義的所有日誌。還可在配置文件中的針對文件設置 <code>encrypt: true</code> 來加密文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journals:</span></span>
<span class="line"><span>  default: ~/journals/journal.txt</span></span>
<span class="line"><span>  work: ~/journals/work.txt</span></span>
<span class="line"><span>  private:</span></span>
<span class="line"><span>    journal: ~/journals/private.txt</span></span>
<span class="line"><span>    encrypt: true</span></span></code></pre></div>`,3)),l("p",null,[t[11]||(t[11]=n("如果日誌尚未加密，系統將提示你輸入在對它進行任何操作的密碼。日誌文件將加密保存在磁盤上，以免受窺探。",-1)),o(s,{href:"https://jrnl.sh/encryption/"},{default:r(()=>[...t[10]||(t[10]=[n("jrnl 文檔",-1)])]),_:1}),t[12]||(t[12]=n(" 中包含其工作原理、使用哪些加密方式等的更多信息。",-1))]),t[31]||(t[31]=l("p",null,[l("img",{src:"https://opensource.com/sites/default/files/uploads/productivity_8-4.png",alt:"Encrypted jrnl file",title:"Encrypted jrnl file"})],-1)),t[32]||(t[32]=l("p",null,"日誌記錄幫助我記住什麼時候做了什麼事，並在我需要的時候能夠找到它。",-1)),t[33]||(t[33]=l("hr",null,null,-1)),l("p",null,[t[14]||(t[14]=n("via: ",-1)),o(s,{href:"https://opensource.com/article/20/1/python-journal"},{default:r(()=>[...t[13]||(t[13]=[n("https://opensource.com/article/20/1/python-journal",-1)])]),_:1})]),l("p",null,[t[19]||(t[19]=n("作者：",-1)),o(s,{href:"https://opensource.com/users/ksonney"},{default:r(()=>[...t[15]||(t[15]=[n("Kevin Sonney",-1)])]),_:1}),t[20]||(t[20]=n(" 選題：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[16]||(t[16]=[n("lujun9972",-1)])]),_:1}),t[21]||(t[21]=n(" 譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:r(()=>[...t[17]||(t[17]=[n("geekpi",-1)])]),_:1}),t[22]||(t[22]=n(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[18]||(t[18]=[n("wxy",-1)])]),_:1})]),l("p",null,[t[25]||(t[25]=n("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[23]||(t[23]=[n("LCTT",-1)])]),_:1}),t[26]||(t[26]=n(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:r(()=>[...t[24]||(t[24]=[n("Linux中國",-1)])]),_:1}),t[27]||(t[27]=n(" 榮譽推出",-1))])])}const P=p(d,[["render",f]]);export{C as __pageData,P as default};
